const icons={developer:'<path d="M4 20h16M6 16V9m6 7V4m6 12v-5"/>',discover:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',wardrobe:'<path d="M10 5a2 2 0 1 1 3 1.7L12 8v2L3 16v2h18v-2l-9-6"/>',style:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',insights:'<path d="M4 20V12m8 8V4m8 16v-7"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4Z"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1"/><path d="m3 17 5-5 4 4 3-6 6 8"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a17 17 0 0 0 0 18 17 17 0 0 0 0-18"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v.1"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',undo:'<path d="M4 4v6h6M4 10a8 8 0 1 1 0 8"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14Z"/>',sliders:'<path d="M4 7h16M4 17h16M8 4v6M16 14v6"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.style}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(v);
const catalog=[
{id:'denim',name:'Relaxed blue denim',category:'Trousers',image:'assets/denim.jpg',price:2299,description:'A blue-denim alternative to the black trousers. Image and price are illustrative.',tags:['Blue','Denim','Relaxed'],retailer:'Sample denim store'},
{id:'cream',name:'Cream camp-collar shirt',category:'Shirts',image:'assets/cream.png',price:2499,description:'A relaxed silhouette and warm cream tone. A camp collar keeps it easy.',tags:['Cream','Relaxed fit','Camp collar'],retailer:'Sample retailer'},
{id:'black',name:'Black chinos',category:'Trousers',image:'assets/trousers.png',price:2999,description:'A clean, tapered shape with a deep black finish.',tags:['Black','Tapered','Everyday'],retailer:'Sample marketplace'},
{id:'tee',name:'White everyday T-shirt',category:'Shirts',image:'assets/tee.jpg',price:999,description:'An easy white crew neck to anchor a casual look.',tags:['White','Crew neck','Short sleeve'],retailer:'Sample retailer'},
{id:'glasses',name:'Matte black sunglasses',category:'Accessories',image:'assets/sunglasses.jpg',price:1599,description:'A rounded frame and matte finish for a quiet statement.',tags:['Black','Rounded frame'],retailer:'Sample accessories store'},
{id:'shoes',name:'White low-top sneakers',category:'Footwear',image:'assets/sneaker.jpg',price:3499,description:'Clean white sneakers with a low profile.',tags:['White','Low top'],retailer:'Sample footwear store'},
{id:'belt',name:'Brown leather belt',category:'Belts',image:'assets/belt.jpg',price:1299,description:'A simple brown belt to tie the outfit together.',tags:['Brown','Leather look'],retailer:'Sample retailer'}];
const product=id=>catalog.find(p=>p.id===id)||state.external?.find(p=>p.id===id);
const seed=()=>({items:['black','tee','glasses','shoes','belt'].map((id,i)=>({...product(id),owned:true,source:'Sample wardrobe',price:i===4?null:product(id).price,purchased:'2026-02-14',reviews:id==='black'?[{date:'2026-08-14',text:'After six months, the button came loose. The fabric still feels good.',rating:4}]:[]})),saved:[],looks:[],mode:'Frugal maxing',metrics:['cpw','variety','spend','wears'],milestoneDismissed:false,wears:Array.from({length:20},(_,i)=>({id:'seed-'+i,date:`2026-08-${String(i+1).padStart(2,'0')}`,items:['black',...(i%6===0?['tee','glasses']:i%6===1?['tee','shoes']:i%6===2?['glasses','shoes']:i%6===3?['tee','belt']:i%6===4?['shoes','belt']:['tee','glasses','shoes'])],occasion:i<9?'Work':i<15?'Evening':i<18?'Travel':'Untagged'}))});
let state=seed();try{const saved=JSON.parse(localStorage.getItem('tbw-atelier-v1'));if(saved?.items&&saved?.wears)state=saved;}catch{}
let storageWarning=false;
const persist=()=>{try{localStorage.setItem('tbw-atelier-v1',JSON.stringify(state));storageWarning=false;return true;}catch{storageWarning=true;return false;}};
const item=id=>state.items.find(i=>i.id===id)||product(id);
let assemblyMode='exploded',wardrobeOpening=false;
let route=location.hash.slice(1)||'discover',category='All',shelf='owned',query='',ref={image:'assets/outfit.png',sample:true,label:'Cream shirt & black chinos'},target='Shirt',importDraft=[],uploadPurpose='discover',styleIds=['cream','black','shoes'],kept=[],previous=null,styleOccasion='Travel',styleTitle='Kerala trip · beach evening',styleMessage='A cream shirt, clean black chinos, and your white sneakers. Easy contrast for an evening out.',personalPhoto=null,insightItem='black',toastTimer,scrolls={},lastFocus;
const main=document.querySelector('main'),dialog=document.querySelector('dialog'),fileInput=document.querySelector('#photo-input');
const tabs=[['discover','Discover'],['wardrobe','My Wardrobe'],['style','Style Me'],['insights','Insights']];
let developerEnabled=false,capabilitiesLoaded=false;
function toast(msg){clearTimeout(toastTimer);const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');toastTimer=setTimeout(()=>t.classList.remove('show'),3500);}
function go(next){if(next===route){render();return;}location.hash=next;}
function nav(){const active=route.split('/')[0];const link=([id,name])=>`<a href="#${id}" class="nav-link ${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(id)}${name}</a>`;const core=tabs.map(link).join('');
 document.querySelector('#desktop-nav').innerHTML=developerEnabled?core+link(['developer','Developer']):core;
 document.querySelector('#bottom-nav').innerHTML=core;
 const devLink=document.querySelector('#developer-link');if(devLink){devLink.innerHTML=icon('developer');devLink.classList.toggle('enabled',developerEnabled);devLink.classList.toggle('active',active==='developer');}
}
function modal(title,body,actions=''){lastFocus=document.activeElement;document.querySelector('#dialog-content').innerHTML=`<div class="modal"><div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}${actions?`<div class="modal-actions">${actions}</div>`:''}</div>`;if(!dialog.open)dialog.showModal();}
function close(){dialog.close();if(lastFocus?.isConnected)lastFocus.focus();}
function img(p,extra=''){return `<div class="well ${extra}"><img src="${esc(p.image)}" alt="${esc(p.name||p.label)}" loading="lazy"></div>`;}
function notice(text='Sample data · saved on this device only'){return `<div class="preview-notice">${icon('info')} ${text}${storageWarning?' · Storage full: new changes last for this session only.':''}</div>`;}
function heading(title,desc='',action=''){return `<div class="page-head"><div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`;}
function chip(label,action,value,active=false){return `<button class="chip ${active?'active':''}" data-action="${action}" data-value="${esc(value)}" aria-pressed="${active}">${esc(label)}</button>`;}
function discover(){return `<div class="eyebrow">The after-hours atelier</div>${heading('Find your <em>next</em> look.','',`<span class="pill">${icon('globe')} India first. Inspiration everywhere.</span>`)}<div class="entry-grid"><div><div class="upload-zone" id="drop-zone"><div class="upload-illustration"><img src="assets/cream.png" alt="Cream shirt example">${icon('plus')}</div><h2>Drop a screenshot. Find the vibe.</h2><p>Any app, any film still, any saved photo. We chase the vibe — never a promise of the exact piece.</p><button class="btn" data-action="upload-discover">${icon('upload')} Upload screenshot</button><span class="note">JPG, PNG or WebP · up to 10 MB</span></div><div class="entry-foot"><span class="note">Photos stay local until you start AI analysis or search.</span><button class="link-btn" data-action="sample" data-value="Shirt">Try an example ${icon('arrow')}</button></div><div class="future-input"><div class="row between"><span class="small">Have a link or a look in mind?</span><span class="pill">Later release</span></div><p class="note">Image-first for now. Link and natural-language discovery are next.</p></div></div><div><div class="section-head start"><h2>Start from a reference</h2><button class="link-btn" data-action="references">See all</button></div><div class="collections">${[['cream','Draper-coded','Shirt'],['denim','Oversized denim','Trousers'],['glasses','The finishing touch','Accessories']].map(([id,name,t])=>`<button class="collection" data-action="sample" data-value="${t}">${img(product(id))}<h3>${name}</h3></button>`).join('')}</div><div class="editorial-note"><span class="mini-ribbon ribbon" aria-hidden="true"></span><h2>Good taste.<br><em>Your own take.</em></h2><p>Find the pieces. Remix what you own.<br>Make a little room for the unexpected.</p><div class="tiny-rule"></div><span class="eyebrow">A wardrobe, connected.</span></div></div></div><div class="note-box">${notice('Upload your own screenshot for live discovery. Reference collections remain illustrative examples.')}</div>`;}
function selection(){if(!ref.sample&&window.Discovery)return window.Discovery.selection(ref);const targetProduct=product(target==='Trousers'?'black':target==='Accessories'?'glasses':'cream');return `<div class="toolbar"><button class="link-btn" data-action="go" data-value="discover">${icon('back')} Back</button><button class="link-btn" data-action="upload-discover">Replace image</button></div>${heading('Which piece are we <em>chasing?</em>','Choose a garment, or search the whole look.')}<div class="selection-layout"><div class="panel reference-panel"><img class="reference-photo" src="${esc(ref.image)}" alt="${esc(ref.label)}">${ref.sample?`<button class="target-box target-shirt ${target==='Shirt'?'chosen':''}" data-action="target" data-value="Shirt" aria-label="Select shirt in sample reference"><span>Shirt</span></button><button class="target-box target-trousers ${target==='Trousers'?'chosen':''}" data-action="target" data-value="Trousers" aria-label="Select trousers in sample reference"><span>Trousers</span></button>`:''}<span class="reference-caption">${ref.sample?'Sample reference':'Your uploaded reference'}</span></div><div class="stack"><div class="chip-row">${['Shirt','Trousers','Accessories','Whole look'].map(t=>chip(t,'target',t,target===t)).join('')}</div><div class="panel row">${img(targetProduct,'thumb')}<div><strong>${ref.sample?esc(targetProduct.name):esc(target)+' selected'}</strong><p class="note">${ref.sample?'Example search target':'Selected by you · no image recognition yet'}</p></div></div><div><h3>${ref.sample?'Reference details':'Describe what matters'}</h3><div class="chip-row spaced">${(ref.sample?targetProduct.tags:['Colour','Shape','Overall vibe']).map(t=>`<span class="pill">${esc(t)}</span>`).join('')}<span class="pill warn">Fabric — not verified</span></div></div><label class="field">Optional detail<input id="target-detail" placeholder="e.g. keep the relaxed fit" maxlength="160"></label><div class="panel raised"><p class="note">${ref.sample?'This example shows the intended selection flow.':'Your image is displayed locally. Select the target manually for this walkthrough.'} The next screen contains sample matches, not live search results.</p></div><button class="btn full" data-action="matches">View sample matches ${icon('arrow')}</button></div></div>`;}
function resultCard(p,global=false){const saved=state.saved.includes(p.id),owned=state.items.some(i=>i.id===p.id);return `<article class="result-card"><button class="result-image" data-action="product" data-id="${p.id}" aria-label="View ${esc(p.name)}">${img(p)}</button><div class="result-content"><div class="row between"><button class="product-name" data-action="product" data-id="${p.id}">${esc(p.name)}</button><button class="icon-btn save-btn ${saved?'saved':''}" data-action="save" data-id="${p.id}" aria-label="${saved?'Unsave':'Save'} ${esc(p.name)}" aria-pressed="${saved}">${icon(saved?'check':'bookmark')}</button></div><p class="note">${global?'Sample store (US) · $68':esc(p.retailer)+' · '+money(p.price)}</p><div class="chip-row"><span class="pill rose">Similar style · demo</span><span class="pill warn">${global?'India delivery unknown':'Availability not checked'}</span>${owned?'<span class="pill green">In your wardrobe</span>':''}</div><p class="match-copy">${esc(p.description)}</p><div class="row"><button class="link-btn" data-action="product" data-id="${p.id}">View piece ${icon('arrow')}</button><button class="link-btn" data-action="style-item" data-id="${p.id}">Style it</button></div></div></article>`;}
function results(){if(!ref.sample&&window.Discovery)return window.Discovery.results();const list=target==='Trousers'?[product('black'),product('denim')]:target==='Accessories'?[product('glasses'),product('belt')]:target==='Whole look'?[product('cream'),product('black'),product('glasses')]:[product('cream'),product('tee')];return `<div class="reference-strip"><img src="${esc(ref.image)}" alt="Reference thumbnail"><div><strong>${esc(target==='Whole look'?'The complete look':target+' inspiration')}</strong><p class="note">Searching the vibe, not the exact piece</p></div><button class="link-btn" data-action="go" data-value="discover/select">Change</button></div>${notice('Demonstration catalog · example prices · no live matching or stock verification.')}<div class="results-layout"><div><div class="section-head start"><h2>India shopping options <span class="count">${list.length}</span></h2><span class="pill">India</span></div><div class="stack">${list.map(p=>resultCard(p)).join('')}</div></div><aside><div class="section-head start"><h2>Global matches</h2>${icon('globe')}</div>${resultCard(product(target==='Trousers'?'black':target==='Accessories'?'glasses':'cream'),true)}<div class="note-box note">Exact-item identification is not connected. These examples show how similar pieces and delivery information will be presented.</div><button class="link-btn" data-action="go" data-value="discover/select">Try another target ${icon('arrow')}</button></aside></div>`;}
function wardrobeLevel(count){const levels=[[100,5,'Tastemaker'],[60,4,'Archivist'],[30,3,'Curator'],[15,2,'Stylist'],[0,1,'Collector']];const x=levels.find(([n])=>count>=n);return {number:x[1],title:x[2]};}
function wardrobeAdd(){const n=Math.min(state.items.length,5),left=Math.max(0,5-n),unlocked=n>=5;return `<div class="wardrobe-screen wardrobe-add"><div class="wardrobe-head"><h1>My Wardrobe</h1><button data-action="wardrobe-skip">Skip</button></div><div class="unlock-card"><div><strong>Level 1 · Collector</strong><span>${n} / 5 pieces</span></div><div class="unlock-track"><i style="width:${n/5*100}%"></i></div><p>${unlocked?'Your wardrobe is unlocked.':`Add ${left} more ${left===1?'piece':'pieces'} and your wardrobe doors unlock.`}</p></div><div class="wardrobe-label">Pick a way in</div><div class="source-list"><button data-action="upload-wardrobe"><i class="source-icon camera"></i><span><strong>Snap your clothes</strong><small>Cleanest cutouts · +10 XP each</small></span><b>→</b></button><button data-action="upload-wardrobe"><i class="source-icon gallery"></i><span><strong>Import from gallery</strong><small>Up to 20 photos at once</small></span><b>→</b></button><button class="recommended" data-action="social"><i class="source-icon social"></i><span><em>Fastest start</em><strong>Connect Instagram or Facebook</strong><small>Pick outfit photos and pre-fill your pieces</small></span><b>→</b></button></div><p class="wardrobe-note">We only read the photos you pick. Nothing is ever posted from your account.</p><div class="wardrobe-dock"><button class="wardrobe-primary" data-action="${unlocked?'wardrobe-open':'upload-wardrobe'}">${unlocked?'Open wardrobe':'Open camera →'}</button></div></div>`;}
function wardrobeClosed(){const n=state.items.length,level=wardrobeLevel(n);if(!n)return `<div class="wardrobe-screen">${heading('Your wardrobe','Empty for now')}<div class="almirah closed empty"><div class="doors"><button class="door left" data-action="add-photos" aria-label="Add your first piece"><i></i></button><span class="seam"></span><button class="door right" data-action="add-photos" aria-label="Add your first piece"><i></i></button><span class="count-plate">Empty for now</span></div></div><div class="wardrobe-dock"><button class="wardrobe-primary" data-action="add-photos">Add your first piece →</button></div></div>`;return `<div class="wardrobe-screen"><div class="status-pills"><span>Level ${level.number} · ${level.title}</span><span>5-day streak</span></div><div class="wardrobe-title"><h1>Your wardrobe</h1><p>${n} pieces · ${Math.min(6,n)} ready for a remix</p></div><div class="almirah closed ${wardrobeOpening?'opening':''}"><div class="almirah-interior-preview"></div><div class="doors"><button class="door left" data-action="wardrobe-open" aria-label="Open wardrobe"><i></i></button><span class="seam"></span><button class="door right" data-action="wardrobe-open" aria-label="Open wardrobe"><i></i></button><button class="count-plate" data-action="wardrobe-open">${n} pieces inside</button></div><button class="open-hint" data-action="wardrobe-open">Tap the doors to open <span>↕</span></button></div><div class="wardrobe-dock two"><button class="wardrobe-add-btn" data-action="add-photos" aria-label="Add pieces">+</button><button class="wardrobe-primary" data-action="wardrobe-open">Open wardrobe</button></div></div>`;}
function wardrobeOpen(){const items=category==='All'?state.items:state.items.filter(p=>p.category===category),hanging=items.filter(p=>['Shirts','Dresses','Suits','Outerwear'].includes(p.category)),folded=items.filter(p=>['Trousers','Footwear'].includes(p.category)),drawer=items.filter(p=>['Accessories','Belts','Jewellery'].includes(p.category));const counts=Object.fromEntries(['Shirts','Trousers','Accessories','Footwear','Belts'].map(c=>[c,state.items.filter(p=>p.category===c).length]));const tile=(p,klass='')=>`<button class="${klass}" data-action="wardrobe-look" data-id="${p.id}" aria-label="Open ${esc(p.name)}"><span class="hook"></span>${img(p)}<strong>${esc(p.name)}</strong></button>`;return `<div class="wardrobe-screen open-screen"><div class="wardrobe-head"><button data-action="wardrobe-close">← Close</button><button data-action="add-photos">+ Add pieces</button></div><div class="almirah-chips">${chip(`All ${state.items.length}`,'almirah-category','All',category==='All')}${Object.entries(counts).filter(([,n])=>n).map(([c,n])=>chip(`${c} ${n}`,'almirah-category',c,category===c)).join('')}</div><div class="almirah interior">${hanging.length?`<section class="rail-section"><div class="wood-label"><strong>On the rail</strong><span>${hanging.length} hanging</span></div><div class="rail"></div><div class="hangers">${hanging.map(p=>tile(p,'hanger-item')).join('')}</div></section>`:''}${folded.length?`<section class="shelf-section"><div class="wood-label"><strong>Folded shelf</strong></div><div class="folded-row">${folded.map(p=>tile(p,'folded-item')).join('')}<button class="more-tile">+ ${Math.max(2,state.items.length-folded.length)} more</button></div></section>`:''}<section class="drawer-section"><div class="wood-label"><strong>Drawer · Belts & jewellery</strong></div><div class="drawer-face">${drawer.map(p=>tile(p,'drawer-item')).join('')||'<span class="drawer-empty">Room for the finishing touches</span>'}<small>Tap any piece to explode it</small></div></section></div><div class="streak-dock"><div><strong>Keep your 5-day streak</strong><small>Log what you wore today · +15 XP</small></div><button data-action="wear-look">Log wear</button></div></div>`;}
function wardrobeExploded(){const focused=route.split('/').pop(),chosen=item(focused)||state.items[0],ids=[chosen.id,...state.items.filter(p=>p.id!==chosen.id).slice(0,3).map(p=>p.id)],level=wardrobeLevel(state.items.length);return `<div class="wardrobe-screen exploded-screen"><div class="wardrobe-head"><button data-action="wardrobe-open-route">← Close</button><div class="assembly-toggle"><button class="${assemblyMode==='exploded'?'active':''}" data-action="assembly-mode" data-value="exploded">Exploded</button><button class="${assemblyMode==='stacked'?'active':''}" data-action="assembly-mode" data-value="stacked">Stacked</button></div></div><div class="wardrobe-title"><h1>${esc(chosen.name)} look</h1><p>${ids.length} pieces · all owned · Level ${level.number} ${level.title}</p></div><div class="assembly-panel ${assemblyMode}"><span class="assembly-axis"></span>${ids.map((id,i)=>{const p=item(id),wears=state.wears.filter(w=>w.items.includes(id)).length;return `<button class="assembly-piece ${id===focused?'focused':''}" style="--step:${i}" data-action="item" data-id="${id}">${img(p)}<span><strong>${esc(p.name)}</strong><small>Owned · worn ${wears}×${p.price&&wears?' · '+money(p.price/wears)+' / wear':''}</small></span></button>`;}).join('')}</div><div class="quick-actions"><button data-action="style-item" data-id="${focused}">Swap the ${esc(chosen.category.toLowerCase())}</button><button data-action="go" data-value="discover">Find similar</button><span>+15 XP</span></div><div class="wardrobe-dock two"><button class="wardrobe-save" data-action="wear-look">Log wear</button><button class="wardrobe-primary" data-action="style-item" data-id="${focused}">Style this look →</button></div></div>`;}
function wardrobe(){if(route==='wardrobe/add'||(state.items.length<5&&route==='wardrobe'))return wardrobeAdd();if(route==='wardrobe/open')return wardrobeOpen();if(route.startsWith('wardrobe/look/'))return wardrobeExploded();return wardrobeClosed();}
function startDemoImport(){importDraft=[{...product('cream'),draftId:'d1',selected:true,warning:''},{...product('black'),id:'black-new',draftId:'d2',selected:false,warning:'Possible repeat of Black chinos. Compare before saving.',duplicate:'black'},{...product('belt'),id:'belt-new',draftId:'d3',selected:false,warning:'Possible repeat of Brown leather belt.',duplicate:'belt'},{id:'unclear',name:'Footwear — unclear',category:'Footwear',image:'assets/outfit.png',draftId:'d4',selected:false,warning:'Mostly out of frame. Replace the photo to add this piece.',unclear:true}];go('wardrobe/import');}
function importScreen(){const selected=importDraft.filter(p=>p.selected&&!p.unclear).length;return `<div class="toolbar"><button class="link-btn" data-action="go" data-value="wardrobe">${icon('back')} Back to wardrobe</button><button class="link-btn" data-action="upload-wardrobe">Add more photos</button></div>${heading('Make room for <em>your pieces.</em>','Check names, categories, and what belongs in your wardrobe.')}${notice(importDraft.some(p=>p.uploaded)?'Manual photo review · automatic garment extraction is not connected.':'Sample import review · these are demonstration candidates.')}<div class="import-layout"><div class="stack">${importDraft.map(p=>`<article class="import-card ${p.selected?'selected':''} ${p.warning?'attention':''}"><input type="checkbox" class="draft-check" aria-label="Select ${esc(p.name)}" data-draft="${p.draftId}" ${p.selected?'checked':''} ${p.unclear?'disabled':''}>${img(p,'thumb')}<div class="import-fields"><label class="sr-only" for="name-${p.draftId}">Item name</label><input id="name-${p.draftId}" data-draft-name="${p.draftId}" value="${esc(p.name)}" maxlength="80" ${p.unclear?'disabled':''}><label class="sr-only" for="category-${p.draftId}">Category</label><select id="category-${p.draftId}" data-draft-category="${p.draftId}" ${p.unclear?'disabled':''}>${['Shirts','Trousers','Accessories','Footwear','Belts','Dresses'].map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select>${p.warning?`<p class="note warning">${esc(p.warning)}</p>`:'<p class="note">Brand not specified · you can rename this</p>'}${p.duplicate?`<button class="link-btn" data-action="compare-duplicate" data-id="${p.draftId}">Compare existing item</button>`:''}${p.unclear?'<button class="link-btn" data-action="upload-wardrobe">Use another photo</button>':''}</div></article>`).join('')||'<div class="empty"><h2>Add your first photos</h2><p>Choose a small batch to get started.</p><button class="btn" data-action="upload-wardrobe">Choose photos</button></div>'}</div><aside class="panel import-summary"><div class="eyebrow">Your collection, coming together</div><h2><span id="selected-count">${selected}</span> pieces<br>ready to add.</h2><p class="note spaced">Only selected pieces will be saved. Uncertain items can wait until you have a better photo.</p><button class="btn full" id="save-import" data-action="save-import" ${selected?'':'disabled'}>Save ${selected} ${selected===1?'piece':'pieces'}</button><button class="link-btn" data-action="discard-import">Discard this import</button></aside></div>`;}
function board(ids,small=false){return `<div class="outfit-board ${small?'compact':''}">${ids.map((id,i)=>{const p=item(id);return p?`<div class="board-piece piece-${i}">${img(p)}<span>${esc(p.name)}</span></div>`:''}).join('')}</div>`;}
function style(){const owned=styleIds.filter(id=>state.items.some(p=>p.id===id)),missing=styleIds.filter(id=>!owned.includes(id));return `${heading(styleTitle.split(' · ').map((t,i)=>i?`<em>${esc(t)}</em>`:esc(t)).join(' · '),'Make a look. Then make it yours.',`<button class="link-btn" data-action="undo" ${previous?'':'disabled'}>${icon('undo')} Undo</button>`)}${notice('Outfit board · preset styling demonstration, not personal AI try-on.')}<div class="studio-layout"><div><div class="studio-preview"><span class="pill preview-badge">Outfit board</span>${board(styleIds)}<button class="compare-btn" data-action="compare" ${previous?'':'disabled'}>Compare looks</button></div><div class="row between spaced"><button class="link-btn" data-action="personal-photo">${icon('image')} Add my photo</button><button class="link-btn" data-action="save-look">${icon('bookmark')} Save look</button></div>${personalPhoto?`<div class="panel row"><img class="personal-thumb" src="${esc(personalPhoto)}" alt="Your original photo"><div><strong>Your original photo</strong><p class="note">Stored locally for this session. AI try-on is not connected.</p></div><button class="icon-btn" data-action="remove-personal" aria-label="Remove personal photo">${icon('close')}</button></div>`:''}</div><div class="stack"><div class="piece-tray">${styleIds.map(id=>{const p=item(id);return `<div class="tray-card ${kept.includes(id)?'kept':''}"><button class="tray-select" data-action="swap" data-id="${id}">${img(p)}<strong>${esc(p.name)}</strong></button><button class="keep-btn" data-action="keep" data-id="${id}" aria-pressed="${kept.includes(id)}">${kept.includes(id)?icon('lock'):icon('plus')} ${kept.includes(id)?'Kept':owned.includes(id)?'Owned · keep':'Addition · keep'}</button></div>`}).join('')}</div><div class="panel row between gap-summary"><div><strong>${owned.length} pieces owned · ${missing.length} ${missing.length===1?'addition':'additions'}</strong><p class="note">${missing.length?'Complete the look with '+missing.map(id=>item(id).name.toLowerCase()).join(', ')+'.':'Everything in this look is already in your wardrobe.'}</p></div>${missing.length?`<button class="btn" data-action="shop-look">Shop ${missing.length}</button>`:`<button class="btn" data-action="wear-look">Wore this</button>`}</div><div class="chip-row">${chip('Beach evening','occasion','Travel',styleOccasion==='Travel')}${chip('Formal setting','occasion','Work',styleOccasion==='Work')}${chip('Date night','occasion','Evening',styleOccasion==='Evening')}</div><div class="style-response"><span class="ribbon mini-ribbon" aria-hidden="true"></span><p>${esc(styleMessage)}</p></div><div class="chip-row">${chip('Swap trousers','swap-type','Trousers')}${chip('Add accessories','accessory','glasses')}${chip('Use only my wardrobe','owned-only','')}</div><form id="style-form" class="prompt-input"><input name="prompt" aria-label="Ask to style your outfit" placeholder="Keep the shirt, add accessories…" maxlength="250" required><button class="btn" type="submit" aria-label="Send styling request">${icon('arrow')}</button></form><p class="note">Try “formal”, “beach”, “white tee”, or “accessories” to explore preset responses.</p>${state.looks.length?`<button class="link-btn" data-action="saved-looks">${state.looks.length} saved ${state.looks.length===1?'look':'looks'} ${icon('arrow')}</button>`:''}</div></div>`;}
function itemStats(id){const p=item(id);const logs=state.wears.filter(w=>w.items.includes(id));return {p,logs,cpw:p?.price!=null&&logs.length?p.price/logs.length:null,variety:new Set(logs.map(w=>[...w.items].sort().join('|'))).size};}
function insights(){if(!state.items.length)return `${heading('Insights','Your wardrobe story starts with a piece.')}<div class="empty"><h2>A little more context, first.</h2><p>Add an item to see its usage, cost, and condition over time.</p><button class="btn" data-action="add-photos">Add your first piece</button></div>`;if(!state.items.some(p=>p.id===insightItem))insightItem=state.items[0].id;const s=itemStats(insightItem),{p,logs,cpw,variety}=s;const spend=state.items.reduce((a,p)=>a+(p.price||0),0),missing=state.items.filter(p=>p.price==null).length;const cards={cpw:['Cost per wear',cpw==null?'—':money(cpw),p.price==null?'Add a purchase price':`${money(p.price)} ÷ ${logs.length} recorded wears`],variety:['Outfit variety',variety,'Logged combinations, not suggestions'],spend:['Wardrobe spend',money(spend),`${state.items.length-missing} of ${state.items.length} prices recorded`],wears:['Recorded wears',logs.length,'For this item · all recorded history'],reviews:['Condition notes',p.reviews?.length||0,'Your observations over time']};const modeText=state.mode==='Frugal maxing'?`Your ${p.name.toLowerCase()} appears in ${variety} logged outfits.`:state.mode==='Splurge'?`What has your ${p.name.toLowerCase()} brought to your wardrobe?`:state.mode==='YOLO'?'Your style, on your terms.':`Your lens on ${p.name.toLowerCase()}.`;return `${heading('Insights','What your clothes do for you.',`<button class="icon-btn" data-action="custom-metrics" aria-label="Customize metrics">${icon('sliders')}</button>`)}${notice()}<div class="insight-controls"><div class="chip-row">${['Frugal maxing','Splurge','YOLO','Custom'].map(m=>chip(m,'mode',m,state.mode===m)).join('')}</div><label class="item-select">Explore item<select id="insight-item">${state.items.map(x=>`<option value="${x.id}" ${x.id===insightItem?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label></div><div class="insight-layout"><div class="stack"><div class="panel raised insight-story"><div class="eyebrow">${esc(state.mode)} / your perspective</div><h2>${esc(modeText)}</h2><p class="note spaced">${state.mode==='YOLO'?'Enjoyment and self-expression matter too. Social engagement is not connected in this preview.':'From your recorded history. Change the lens; keep the evidence.'}</p></div><div class="metric-grid">${state.metrics.filter(k=>cards[k]).map(k=>`<div class="panel metric-card"><span class="note">${cards[k][0]}</span><strong>${cards[k][1]}</strong><p class="note">${cards[k][2]}</p></div>`).join('')}</div><div class="panel"><div class="row between"><strong>Wears by occasion</strong><button class="link-btn" data-action="wear-history">View logs</button></div>${['Work','Evening','Travel','Casual','Untagged'].map(o=>{const n=logs.filter(w=>w.occasion===o).length;return n?`<div class="bar-row"><span>${o}</span><div class="bar-track"><div style="width:${logs.length?n/logs.length*100:0}%"></div></div><strong>${n}</strong></div>`:''}).join('')||'<p class="note spaced">No wears logged yet.</p>'}<p class="note spaced">${logs.filter(w=>w.occasion!=='Untagged').length} of ${logs.length} wears have an occasion tag.</p></div></div><aside class="stack"><div class="panel item-story">${img(p)}<div><h3>${esc(p.name)}</h3><p class="note">${p.purchased?'Owned since '+esc(p.purchased):'Purchase date not recorded'}</p></div>${(p.reviews||[]).slice(-1).map(r=>`<blockquote>“${esc(r.text)}”<cite>Your note · ${esc(r.date)}</cite></blockquote>`).join('')||'<p class="note">How is this piece holding up? Start its story.</p>'}<div class="row"><button class="link-btn" data-action="review" data-id="${p.id}">Add a review</button><button class="link-btn" data-action="style-item" data-id="${p.id}">Style it again ${icon('arrow')}</button></div></div><form class="panel stack" id="insight-form"><h3>Ask your wardrobe</h3><label class="sr-only" for="insight-query">Ask about this item</label><input id="insight-query" name="query" placeholder="Is this getting enough wear?" maxlength="250" required><button class="btn secondary" type="submit">Explore the numbers ${icon('arrow')}</button><span class="note">Uses recorded data and preset explanations.</span></form><p class="note warning">${missing?`${missing} ${missing===1?'piece has':'pieces have'} no purchase price. `:''}Wear logs may be incomplete. These are personal observations, not brand-wide quality ratings.</p></aside></div>`;}
function developer(){queueMicrotask(()=>window.DeveloperDashboard?.load());return window.DeveloperDashboard?.render()||'<div class="empty"><h2>Loading developer tools…</h2></div>';}
function render(){nav();const routes={discover, 'discover/select':selection,'discover/results':results,wardrobe,'wardrobe/add':wardrobe,'wardrobe/open':wardrobe,'wardrobe/import':importScreen,style,insights,developer};if(route.startsWith('wardrobe/look/'))routes[route]=wardrobe;if(!routes[route]){route='discover';history.replaceState(null,'','#discover');nav();}main.innerHTML=`<section class="fade-in">${routes[route]()}</section>`;}
function updateImportCount(){const count=importDraft.filter(p=>p.selected&&!p.unclear).length;document.querySelector('#selected-count').textContent=count;const b=document.querySelector('#save-import');b.textContent=`Save ${count} ${count===1?'piece':'pieces'}`;b.disabled=!count;}
function saveFind(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();toast(state.saved.includes(id)?'Saved to your inspiration.':'Removed from saved inspiration.');}
function productModal(id){const live=product(id);if(live?.live)return modal(esc(live.name),`<div class="item-detail">${img(live)}<div><p>${esc(live.retailer)}</p><p>${esc(live.priceText||'Check price at retailer')}</p><p class="note">${esc(live.description)}</p><a class="btn" href="${esc(live.url)}" target="_blank" rel="noopener noreferrer">Visit listing ↗</a></div></div>`,`<button class="btn secondary" data-action="save" data-id="${live.id}">Toggle saved inspiration</button>`);const p=item(id),owned=state.items.some(i=>i.id===id);modal(esc(p.name),`<div class="product-modal-layout">${img(p)}<div class="stack"><div><strong>${p.price==null?'Price not recorded':money(p.price)}</strong><p class="note">Illustrative item and price</p></div><p>${esc(p.description||'Added from your photo.')}</p><span class="pill ${owned?'green':'rose'}">${owned?'Owned':'Not owned'}</span><p class="note">Live merchant listings and stock are not connected. This panel previews the shopping handoff.</p></div></div>`,`<button class="btn" data-action="style-item" data-id="${id}">Style this piece</button>${owned?'':`<button class="btn secondary" data-action="confirm-own" data-id="${id}">I bought / own this</button><button class="link-btn" data-action="modal-save" data-id="${id}">${state.saved.includes(id)?'Unsave':'Save inspiration'}</button>`}`);}
function itemModal(id){const p=item(id);if(!state.items.some(i=>i.id===id))return productModal(id);const s=itemStats(id);modal(esc(p.name),`<div class="item-detail">${img(p)}<div><span class="pill green">Owned</span><p class="note spaced">${esc(p.category)} · ${s.logs.length} recorded wears</p><p class="note">${p.price==null?'Price not recorded':money(p.price)+' purchase price'}</p><p class="note">${esc(p.source||'My Wardrobe')}</p></div></div>`,`<button class="btn" data-action="style-item" data-id="${id}">Style this</button><button class="btn secondary" data-action="edit-item" data-id="${id}">${icon('edit')} Edit</button><button class="link-btn" data-action="log-item" data-id="${id}">Log a wear</button><button class="link-btn" data-action="review" data-id="${id}">Condition review</button><button class="link-btn" data-action="item-insights" data-id="${id}">View insights</button>`);}
function remember(){previous={ids:[...styleIds],title:styleTitle,occasion:styleOccasion,message:styleMessage,kept:[...kept]};}
function styleItem(id){close();remember();const p=item(id);if(['Shirts','Trousers','Footwear'].includes(p.category))styleIds=styleIds.filter(x=>item(x)?.category!==p.category);if(!styleIds.includes(id))styleIds.unshift(id);styleIds=styleIds.slice(0,4);kept=kept.filter(x=>styleIds.includes(x));styleTitle=`Built around · ${p.name}`;styleMessage=`Start with ${p.name.toLowerCase()}. Keep the pieces you love and try a different pairing.`;go('style');}
function swapModal(id){const p=item(id);const choices=[...state.items,...catalog.filter(p=>!state.items.some(i=>i.id===p.id))].filter(x=>x.id!==id&&x.category===p.category);modal(`Swap ${esc(p.name)}`,kept.includes(id)?'<p>This piece is kept. Unkeep it first to try alternatives.</p>':`<div class="swap-grid">${choices.map(x=>`<button class="swap-option" data-action="swap-to" data-id="${x.id}" data-old="${id}">${img(x)}<strong>${esc(x.name)}</strong><span class="note">${state.items.some(i=>i.id===x.id)?'Owned':'Suggested addition'}</span></button>`).join('')||'<p>No other pieces in this category yet. Add a photo to grow your options.</p>'}</div>`);}
function addOwned(id){const p=product(id);if(state.items.some(i=>i.id===id)){toast('Already in your wardrobe.');close();return;}state.items.push({...p,owned:true,source:'Confirmed from Discover · sample item',purchased:new Date().toISOString().slice(0,10),reviews:[]});persist();close();render();toast('Added to My Wardrobe.');}
function addPhotos(){modal('Bring your wardrobe in.',`<p>Start with up to five photos. In this prototype, your own uploads use manual naming and categorisation. Try the sample import to explore extraction review and duplicate handling.</p><div class="import-choice"><button class="btn full" data-action="upload-wardrobe">${icon('upload')} Choose my photos</button><button class="btn secondary full" data-action="demo-import">Try sample import</button></div><p class="note">Photos stay in this browser. No social account or AI service is contacted.</p>`);}
function chooseFiles(purpose){uploadPurpose=purpose;fileInput.multiple=purpose==='wardrobe';fileInput.value='';fileInput.click();}
async function filesChosen(files){const valid=[...files].filter(f=>['image/jpeg','image/png','image/webp'].includes(f.type)&&f.size<=10*1024*1024);if(!valid.length){toast('Choose a JPG, PNG or WebP image smaller than 10 MB.');return;}if(valid.length<files.length)toast('Some files were skipped. Use JPG, PNG or WebP under 10 MB.');if(valid.length>5)toast('Using the first five photos.');const data=await Promise.all(valid.slice(0,uploadPurpose==='wardrobe'?5:1).map(f=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>{const check=new Image();check.onload=()=>resolve({url:r.result,name:f.name});check.onerror=()=>reject(new Error('Unreadable image'));check.src=r.result;};r.onerror=reject;r.readAsDataURL(f);})));close();if(uploadPurpose==='discover'){ref={image:data[0].url,label:data[0].name,sample:false};go('discover/select');}else if(uploadPurpose==='personal'){personalPhoto=data[0].url;go('style');render();}else{importDraft.push(...data.map((d,i)=>({id:'upload-'+crypto.randomUUID(),draftId:'draft-'+crypto.randomUUID(),name:d.name.replace(/\.[^.]+$/,''),category:'Shirts',image:d.url,price:null,selected:true,uploaded:true})));go('wardrobe/import');render();}}
function editItem(id){const p=item(id);modal('Edit your piece',`<form id="edit-form" data-id="${id}" class="stack"><label class="field">Name<input name="name" value="${esc(p.name)}" required maxlength="80"></label><label class="field">Category<select name="category">${['Shirts','Trousers','Footwear','Accessories','Belts','Dresses'].map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></label><div class="form-columns"><label class="field">Purchase price (₹)<input name="price" type="number" min="0" max="10000000" step="1" value="${p.price??''}" placeholder="Optional"></label><label class="field">Purchase date<input name="purchased" type="date" max="${new Date().toISOString().slice(0,10)}" value="${esc(p.purchased||'')}"></label></div><button class="btn" type="submit">Save changes</button></form><button class="link-btn danger spaced" data-action="remove-item" data-id="${id}">Remove from wardrobe</button>`);}
function reviewModal(id){const p=item(id);modal('How is it holding up?',`<p class="note">${esc(p.name)} · your personal item history</p><div class="review-history">${(p.reviews||[]).map(r=>`<blockquote>“${esc(r.text)}”<cite>${esc(r.date)} · ${r.rating}/5 condition</cite></blockquote>`).join('')}</div><form id="review-form" data-id="${id}" class="stack"><label class="field">Condition<select name="rating"><option value="5">5 — Like new</option><option value="4">4 — Holding up well</option><option value="3">3 — Some wear</option><option value="2">2 — Needs a repair</option><option value="1">1 — No longer wearable</option></select></label><label class="field">Your note<textarea name="text" placeholder="How are the fabric, stitching, buttons or shape holding up?" required maxlength="600" rows="4"></textarea></label><button class="btn" type="submit">Save condition note</button></form>`);}
function logWear(ids){const owned=ids.filter(id=>state.items.some(p=>p.id===id));if(!owned.length)return toast('Add an owned piece before logging a wear.');modal('Log a wear',`<p class="note">${owned.map(id=>esc(item(id).name)).join(', ')}</p><form class="stack spaced" id="wear-form" data-ids="${owned.join(',')}"><label class="field">When?<input name="date" type="date" value="${new Date().toISOString().slice(0,10)}" max="${new Date().toISOString().slice(0,10)}" required></label><label class="field">Occasion<select name="occasion">${['Work','Evening','Travel','Casual','Untagged'].map(o=>`<option ${o===styleOccasion?'selected':''}>${o}</option>`).join('')}</select></label><button class="btn" type="submit">Confirm I wore this</button><span class="note">Only owned pieces are recorded. This updates your local Insights.</span></form>`);}
function customMetrics(){modal('Your metrics, your lens.',`<form id="metrics-form" class="stack"><p class="note">Choose the numbers you want to see.</p>${[['cpw','Cost per wear'],['variety','Outfit variety'],['spend','Recorded wardrobe spend'],['wears','Recorded wears'],['reviews','Condition notes']].map(([k,n])=>`<label class="check-row"><input type="checkbox" name="metric" value="${k}" ${state.metrics.includes(k)?'checked':''}>${n}</label>`).join('')}<button class="btn" type="submit">Apply my lens</button></form>`);}
function about(){modal('Your Atelier walkthrough',`<p>This is a local, interactive design prototype based on your seven Atelier screens.</p><ol class="walkthrough"><li>Discover → try an example → choose a target → inspect and save a sample match.</li><li>My Wardrobe → Add photos → try the sample import or upload your own → review and save.</li><li>Style Me → keep and swap pieces → save a look → confirm a purchase or log a wear.</li><li>Insights → choose a lens → review a piece → see its recorded history.</li></ol><p class="note">Changes are saved in this browser. Discover supports live search when provider keys are configured. Wardrobe extraction, personal AI try-on, social connections, and checkout remain demonstrations. Example product imagery and prices are illustrative.</p>`,`<button class="btn" data-action="close">Let's explore</button><button class="btn secondary" data-action="reset-confirm">Reset sample data</button>`);}
const actions={
'wardrobe-open':()=>{if(wardrobeOpening)return;wardrobeOpening=true;render();setTimeout(()=>{wardrobeOpening=false;go('wardrobe/open');},520);},'wardrobe-close':()=>go('wardrobe'),'wardrobe-open-route':()=>go('wardrobe/open'),'wardrobe-skip':()=>go('wardrobe'),'almirah-category':b=>{category=b.dataset.value;render();},'wardrobe-look':b=>go('wardrobe/look/'+b.dataset.id),'assembly-mode':b=>{assemblyMode=b.dataset.value;render();},
'close':()=>close(),'about':about,'go':b=>{close();go(b.dataset.value);},'upload-discover':()=>chooseFiles('discover'),'upload-wardrobe':()=>chooseFiles('wardrobe'),'personal-photo':()=>chooseFiles('personal'),'remove-personal':()=>{personalPhoto=null;render();},'add-photos':addPhotos,'sample':b=>{ref={image:'assets/outfit.png',sample:true,label:'Cream shirt & black chinos'};target=b.dataset.value||'Shirt';close();go('discover/select');},'target':b=>{target=b.dataset.value;render();},'matches':()=>go('discover/results'),'references':()=>modal('Pick a starting point',`<div class="collections">${[['cream','Draper-coded','Shirt'],['black','Relaxed tailoring','Trousers'],['glasses','Finishing touches','Accessories']].map(([id,n,t])=>`<button class="collection" data-action="sample" data-value="${t}">${img(product(id))}<h3>${n}</h3></button>`).join('')}</div>`),'product':b=>productModal(b.dataset.id),'item':b=>itemModal(b.dataset.id),'save':b=>saveFind(b.dataset.id),'modal-save':b=>{saveFind(b.dataset.id);close();},'confirm-own':b=>modal('Add this to your wardrobe?',`<p>Confirm that you bought or own <strong>${esc(item(b.dataset.id).name)}</strong>. For this walkthrough, this adds the sample item and price to your local collection.</p>`,`<button class="btn" data-action="add-owned" data-id="${b.dataset.id}">Confirm ownership</button><button class="btn secondary" data-action="close">Keep browsing</button>`),'add-owned':b=>addOwned(b.dataset.id),'style-item':b=>styleItem(b.dataset.id),'shelf':b=>{shelf=b.dataset.value;render();},'category':b=>{category=b.dataset.value;render();},'dismiss':()=>{state.milestoneDismissed=true;persist();render();},'demo-import':()=>{close();startDemoImport();},'discard-import':()=>modal('Discard this import?',`<p>Your existing wardrobe stays as it is. The unsaved candidates will be removed.</p>`,`<button class="btn" data-action="discard-confirm">Discard candidates</button><button class="btn secondary" data-action="close">Keep reviewing</button>`),'discard-confirm':()=>{importDraft=[];close();go('wardrobe');},'save-import':()=>{const selected=importDraft.filter(p=>p.selected&&!p.unclear);if(selected.some(p=>!p.name.trim()))return toast('Give each selected piece a name.');for(const p of selected)state.items.push({...p,id:state.items.some(x=>x.id===p.id)?p.id+'-'+crypto.randomUUID():p.id,owned:true,source:p.uploaded?'Your uploaded photo':'Sample import',reviews:[],price:p.uploaded?null:p.price});importDraft=[];category='All';shelf='owned';query='';persist();go('wardrobe');toast(`${selected.length} pieces added to your wardrobe.`);},'compare-duplicate':b=>{const p=importDraft.find(p=>p.draftId===b.dataset.id),existing=item(p.duplicate);modal('Same piece or another one?',`<div class="compare-grid"><div>${img(existing)}<strong>${esc(existing.name)}</strong><p class="note">Already owned</p></div><div>${img(p)}<strong>${esc(p.name)}</strong><p class="note">Import candidate</p></div></div>`,`<button class="btn" data-action="duplicate-skip" data-id="${p.draftId}">Same piece — skip</button><button class="btn secondary" data-action="duplicate-new" data-id="${p.draftId}">Different piece — add</button>`);},'duplicate-skip':b=>{importDraft.find(p=>p.draftId===b.dataset.id).selected=false;close();render();},'duplicate-new':b=>{const p=importDraft.find(p=>p.draftId===b.dataset.id);p.selected=true;p.warning='Confirmed as a separate piece.';close();render();},'social':()=>modal('Instagram, when you want it.',`<p>The planned connection will let you choose photos to add to your wardrobe. Account access and garment extraction are not connected in this prototype.</p><p class="note spaced">You can explore the same review journey with photos from your device.</p>`,`<button class="btn" data-action="upload-wardrobe">Choose local photos</button>`),'keep':b=>{const id=b.dataset.id;kept=kept.includes(id)?kept.filter(x=>x!==id):[...kept,id];render();},'swap':b=>swapModal(b.dataset.id),'swap-type':b=>{const id=styleIds.find(id=>item(id)?.category===b.dataset.value);if(id)swapModal(id);else toast('No trousers in this look yet. Start from a wardrobe item.');},'swap-to':b=>{remember();styleIds=styleIds.map(id=>id===b.dataset.old?b.dataset.id:id);close();render();toast('Piece swapped. The rest of your look stays.');},'accessory':b=>{if(styleIds.includes(b.dataset.value))return toast('These accessories are already in your look.');remember();styleIds.push(b.dataset.value);render();},'undo':()=>{if(!previous)return;styleIds=previous.ids;styleTitle=previous.title;styleOccasion=previous.occasion;styleMessage=previous.message;kept=previous.kept;previous=null;render();},'compare':()=>{if(previous)modal('Two takes on your look',`<div class="compare-grid"><div><h3>Before</h3>${board(previous.ids,true)}</div><div><h3>Now</h3>${board(styleIds,true)}</div></div>`);},'occasion':b=>setOccasion(b.dataset.value),'owned-only':()=>{remember();styleIds=styleIds.map(id=>state.items.some(p=>p.id===id)?id:(state.items.find(p=>p.category===item(id).category)?.id)).filter(Boolean);styleMessage='This version uses only the pieces you have confirmed as owned.';kept=kept.filter(x=>styleIds.includes(x));render();},'shop-look':()=>{const p=styleIds.filter(id=>!state.items.some(i=>i.id===id));modal('Complete your look',`<p class="note">Example additions · live retailer checkout is not connected.</p><div class="stack spaced">${p.map(id=>`<div class="row">${img(item(id),'thumb')}<div class="grow"><strong>${esc(item(id).name)}</strong><p class="note">${money(item(id).price)} · sample price</p></div><button class="link-btn" data-action="product" data-id="${id}">View</button></div>`).join('')}</div>`);},'wear-look':()=>logWear(styleIds),'log-item':b=>logWear([b.dataset.id]),'save-look':()=>{if(!styleIds.length)return toast('Add a piece to your look first.');if(state.looks.some(l=>l.ids.join(',')===styleIds.join(',')))return toast('This combination is already saved.');state.looks.push({id:crypto.randomUUID(),ids:[...styleIds],title:styleTitle,occasion:styleOccasion});persist();render();toast('Look saved. Your next outfit is ready.');},'saved-looks':()=>modal('Your saved looks',`<div class="stack">${state.looks.map(l=>`<button class="saved-look" data-action="load-look" data-id="${l.id}"><span>${esc(l.title)}</span><span class="note">${l.ids.length} pieces ${icon('arrow')}</span></button>`).join('')}</div>`),'load-look':b=>{const l=state.looks.find(l=>l.id===b.dataset.id);remember();styleIds=l.ids.filter(id=>item(id));styleTitle=l.title;styleOccasion=l.occasion;kept=[];close();go('style');render();},'mode':b=>{state.mode=b.dataset.value;persist();if(state.mode==='Custom')customMetrics();render();},'custom-metrics':customMetrics,'review':b=>reviewModal(b.dataset.id),'edit-item':b=>editItem(b.dataset.id),'item-insights':b=>{insightItem=b.dataset.id;close();go('insights');},'wear-history':()=>{const s=itemStats(insightItem);modal('Recorded wear history',`<p class="note">${esc(s.p.name)} · ${s.logs.length} wears</p><div class="log-list">${[...s.logs].reverse().map(w=>`<div><strong>${esc(w.date)}</strong><span>${esc(w.occasion)}</span><p class="note">${w.items.map(id=>esc(item(id)?.name||'Archived piece')).join(', ')}</p></div>`).join('')||'<p>No wears logged yet.</p>'}</div>`);},'remove-item':b=>modal('Remove this piece?',`<p>Remove <strong>${esc(item(b.dataset.id).name)}</strong> from your wardrobe? Historical wear records will be retained.</p>`,`<button class="btn" data-action="remove-confirm" data-id="${b.dataset.id}">Remove piece</button><button class="btn secondary" data-action="close">Cancel</button>`),'remove-confirm':b=>{state.items=state.items.filter(i=>i.id!==b.dataset.id);if(insightItem===b.dataset.id)insightItem=state.items[0]?.id||'';styleIds=styleIds.filter(id=>id!==b.dataset.id);persist();close();render();toast('Piece removed.');},'reset-confirm':()=>modal('Reset the walkthrough?',`<p>This removes local changes, uploaded photos, reviews, and saved looks from this prototype, and restores the original sample wardrobe.</p>`,`<button class="btn" data-action="reset">Reset sample data</button><button class="btn secondary" data-action="close">Keep my changes</button>`),'reset':()=>{state=seed();persist();importDraft=[];ref={image:'assets/outfit.png',sample:true,label:'Sample look'};personalPhoto=null;styleIds=['cream','black','shoes'];kept=[];previous=null;insightItem='black';category='All';query='';shelf='owned';close();go('discover');render();toast('Fresh start. Sample data restored.');}
};
function setOccasion(o){remember();styleOccasion=o;styleTitle=o==='Travel'?'Kerala trip · beach evening':o==='Work'?'A little more · put together':'Date night · your own take';styleMessage=o==='Travel'?'Keep the silhouette relaxed. A light shirt and simple accessories make this an easy travel look.':o==='Work'?'This is a smart-casual direction. For a strictly formal event, consider dress shoes and a jacket.':'Keep the contrast, add a finishing touch, and wear the version that feels like you.';render();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const fn=actions[b.dataset.action];if(fn)fn(b);});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.draft){const p=importDraft.find(p=>p.draftId===t.dataset.draft);p.selected=t.checked;t.closest('.import-card').classList.toggle('selected',t.checked);updateImportCount();}if(t.dataset.draftCategory)importDraft.find(p=>p.draftId===t.dataset.draftCategory).category=t.value;if(t.id==='insight-item'){insightItem=t.value;render();}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.draftName)importDraft.find(p=>p.draftId===t.dataset.draftName).name=t.value;if(t.id==='wardrobe-search'){query=t.value;const start=t.selectionStart;render();const f=document.querySelector('#wardrobe-search');f.focus();f.setSelectionRange(start,start);}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(f.id==='edit-form'){const p=state.items.find(p=>p.id===f.dataset.id);if(!d.get('name').trim())return toast('Please enter a name.');Object.assign(p,{name:d.get('name').trim(),category:d.get('category'),price:d.get('price')===''?null:Number(d.get('price')),purchased:d.get('purchased')});persist();close();render();toast('Item updated.');}if(f.id==='review-form'){const p=state.items.find(p=>p.id===f.dataset.id);const text=d.get('text').trim();if(!text)return;p.reviews??=[];p.reviews.push({date:new Date().toISOString().slice(0,10),text,rating:Number(d.get('rating'))});persist();close();render();toast('Your condition note is saved.');}if(f.id==='wear-form'){state.wears.push({id:crypto.randomUUID(),date:d.get('date'),occasion:d.get('occasion'),items:f.dataset.ids.split(',').filter(Boolean)});persist();close();render();toast('Wear recorded. Insights updated.');}if(f.id==='metrics-form'){const v=d.getAll('metric');if(!v.length)return toast('Choose at least one metric.');state.metrics=v;state.mode='Custom';persist();close();render();}if(f.id==='style-form'){const q=d.get('prompt').trim().toLowerCase();if(!q)return;if(/formal|office|work/.test(q))setOccasion('Work');else if(/beach|kerala|trip/.test(q))setOccasion('Travel');else if(/date|evening/.test(q))setOccasion('Evening');else if(/accessor|glass|bracelet|ring/.test(q)){actions.accessory({dataset:{value:'glasses'}});styleMessage='For this demonstration, try the black sunglasses as the finishing touch. More accessory types will arrive with the live styling module.';render();}else if(/tee|t-shirt|white/.test(q)){const current=styleIds.find(id=>item(id).category==='Shirts');if(current&&kept.includes(current))return toast('Unkeep your shirt before replacing it.');remember();styleIds=styleIds.filter(id=>item(id).category!=='Shirts');styleIds.unshift('tee');styleMessage='The white tee brings this into a more casual direction. Your other pieces stay in place.';render();}else{styleMessage='This is a preset walkthrough, so I cannot interpret every request yet. Try an occasion above, swap a piece, or ask for a white tee or accessories.';render();}}if(f.id==='insight-form'){const s=itemStats(insightItem);modal('A closer look',`<h3>${esc(s.p.name)}</h3><p class="spaced">You have recorded <strong>${s.logs.length} wears</strong> across <strong>${s.variety} combinations</strong>. ${s.cpw==null?'Add a price and a wear to calculate cost per wear.':`At ${money(s.p.price)}, that is <strong>${money(s.cpw)} per recorded wear</strong>.`}</p><p class="note spaced">This is a calculated summary of the selected item, not a live AI answer to your question. Unlogged wear is not included.</p>`,`<button class="btn" data-action="style-item" data-id="${s.p.id}">Style it again</button><button class="btn secondary" data-action="review" data-id="${s.p.id}">Add a condition note</button>`);}});
fileInput.addEventListener('change',()=>filesChosen(fileInput.files).catch(()=>toast('That photo could not be read. Try another image.')));
document.addEventListener('dragover',e=>{const z=e.target.closest('#drop-zone');if(z){e.preventDefault();z.classList.add('dragover');}});document.addEventListener('dragleave',e=>e.target.closest('#drop-zone')?.classList.remove('dragover'));document.addEventListener('drop',e=>{if(e.target.closest('#drop-zone')){e.preventDefault();uploadPurpose='discover';filesChosen(e.dataTransfer.files).catch(()=>toast('Could not read the image.'));}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
window.addEventListener('hashchange',()=>{scrolls[route]=window.scrollY;route=location.hash.slice(1)||'discover';render();window.scrollTo(0,scrolls[route]||0);main.focus({preventScroll:true});});
render();
if(typeof fetch==='function')fetch('/api/discover/status').then(r=>r.ok?r.json():{}).then(status=>{developerEnabled=!!status.developerDashboard;capabilitiesLoaded=true;if(route==='developer'&&!developerEnabled)go('discover');else render();}).catch(()=>{capabilitiesLoaded=true;if(route==='developer')go('discover');});

// Optional agent navigation over the same local preview; no external services.
if (document.modelContext?.registerTool) {
  const lifecycle = new AbortController();
  const snapshot = () => ({route,ownedCount:state.items.length,savedCount:state.saved.length,lookCount:state.looks.length,mode:state.mode,liveAI:false});
  for (const tool of [
    {name:'get_wardrobe_preview_state',title:'Read wardrobe preview state',description:'Read the current screen and local collection counts. Does not modify the prototype.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>snapshot()},
    {name:'navigate_wardrobe_preview',title:'Navigate wardrobe preview',description:'Open one of the existing walkthrough screens. Does not upload, purchase, or change owned items.',inputSchema:{type:'object',properties:{screen:{type:'string',enum:['discover','discover/select','discover/results','wardrobe','wardrobe/import','style','insights']}},required:['screen'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!['discover','discover/select','discover/results','wardrobe','wardrobe/import','style','insights'].includes(input.screen))throw new Error('Unknown preview screen');go(input.screen);route=input.screen;render();return snapshot();}}
  ]) {
    try { Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{}); } catch {}
  }
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}

if(window.Discovery)window.Discovery.onSave(p=>{state.external??=[];const id='live-'+p.id;const entry={id,live:true,name:p.title,category:({Shirt:'Shirts',Trousers:'Trousers',Dress:'Dresses',Suit:'Suits',Blazer:'Outerwear',Jacket:'Outerwear',Vest:'Outerwear',Shoes:'Footwear',Belt:'Belts'})[p.category]||'Accessories',image:p.image||ref.image,price:null,priceText:p.priceText,retailer:p.merchant,url:p.url,description:p.availability,tags:[p.match]};const index=state.external.findIndex(x=>x.id===id);if(index<0)state.external.push(entry);else state.external[index]=entry;if(!state.saved.includes(id))state.saved.push(id);persist();toast('Saved to My Wardrobe → Saved inspiration.');});
